def _parse_datetime(value):
    """
    Attempt to parse a value as an ISO 8601 datetime.
    Handles the trailing 'Z' (UTC) that datetime.fromisoformat doesn't accept
    in Python < 3.11, and date-only strings like "2026-02-18".
    Returns a timezone-aware datetime or None if parsing fails.
    """
    if not isinstance(value, str):
        return None
    try:
        normalized = value.replace("Z", "+00:00")
        dt = datetime.fromisoformat(normalized)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    except (ValueError, TypeError):
        return None


def evaluate_filter(record, filter_item):
    """
    Evaluate a single filter condition against a record.

    Args:
        record: The record object to evaluate
        filter_item: A filter object with fieldId, filterType, value, field, ignoreCase, etc.

    Returns:
        bool: True if the filter matches, False otherwise
    """
    field_obj = filter_item.get("field", {})
    field_type = field_obj.get("$type", "")
    field_key = field_obj.get("key")

    if not field_key:
        return False

    filter_type = filter_item.get("filterType")
    filter_value = filter_item.get("value")
    # Account for single select fields.
    if field_type=="Core.Models.Fields.ValuesListField, Core":
        search_value = filter_value
        values = field_obj.get("values",[])
        filter_value = next(f["name"] for f in values if f["id"]==search_value)

    ignore_case = filter_item.get("ignoreCase", False)
    record_value = record.get(field_key)


    if filter_type == "equals":
        return op_equals(record_value, filter_value, ignore_case)

    elif filter_type == "doesNotEqual":
        return not op_equals(record_value, filter_value, ignore_case)

    elif filter_type == "contains":
        return op_contains(record_value, filter_value, ignore_case)

    elif filter_type == "doesNotContain":
        return not op_contains(record_value, filter_value, ignore_case)

    elif filter_type == "lessThan":
        return op_less_than(record_value, filter_value)

    elif filter_type == "greaterThan":
        return op_greater_than(record_value, filter_value)

    elif filter_type == "lessThanOrEqual":
        return op_less_than_or_equal(record_value, filter_value)

    elif filter_type == "greaterThanOrEqual":
        return op_greater_than_or_equal(record_value, filter_value)

    elif filter_type == "isNull":
        return op_is_null(record_value)

    elif filter_type == "isNotNull":
        return not op_is_null(record_value)

    else:
        print(f"Unknown filter type: {filter_type}")
        return False


def op_equals(record_value, filter_value, ignore_case=False):
    """
    Check if record_value equals filter_value.
    Supports case-insensitive string comparison and datetime normalization
    so that equivalent ISO representations (e.g. trailing Z vs +00:00,
    varying fractional-second precision) compare as equal.
    """
    if record_value is None and filter_value is None:
        return True
    if record_value is None or filter_value is None:
        return False

    dt_rec = _parse_datetime(record_value)
    dt_filt = _parse_datetime(filter_value)
    if dt_rec is not None and dt_filt is not None:
        return dt_rec == dt_filt

    if ignore_case and isinstance(record_value, str) and isinstance(filter_value, str):
        return record_value.lower() == filter_value.lower()

    if isinstance(record_value, list):
        return record_value == filter_value

    return record_value == filter_value


def op_contains(record_value, filter_value, ignore_case=False):
    """
    Check if record_value contains filter_value.
    - For strings: substring check
    - For lists: membership check (is filter_value in the list?)
    """
    if record_value is None or filter_value is None:
        return False

    if isinstance(record_value, list):
        if ignore_case and isinstance(filter_value, str):
            filter_lower = filter_value.lower()
            return any(
                (isinstance(item, str) and filter_lower in item.lower()) or
                (isinstance(item, str) and item.lower() == filter_lower)
                for item in record_value
            )
        return any(
            (isinstance(item, str) and filter_value in item) or
            item == filter_value
            for item in record_value
        )

    if isinstance(record_value, str):
        if ignore_case:
            return filter_value.lower() in record_value.lower()
        return str(filter_value) in record_value

    return str(filter_value) in str(record_value)


def op_less_than(record_value, filter_value):
    """Numeric or datetime less-than comparison."""
    dt_rec = _parse_datetime(record_value)
    dt_filt = _parse_datetime(filter_value)
    if dt_rec is not None and dt_filt is not None:
        return dt_rec < dt_filt
    try:
        return float(record_value) < float(filter_value)
    except (TypeError, ValueError):
        return False


def op_greater_than(record_value, filter_value):
    """Numeric or datetime greater-than comparison."""
    dt_rec = _parse_datetime(record_value)
    dt_filt = _parse_datetime(filter_value)
