def evaluate_group(record, group):
    """
    Evaluate a group of filters with AND/OR logic.

    Args:
        record: The record object to evaluate
        group: A group object with filterOperationType ("And" or "Or") and filters array

    Returns:
        bool: True if the group condition is met, False otherwise
    """
    operation_type = group.get("filterOperationType", "And")
    filters = group.get("filters", [])

    if not filters:
        return True

    if operation_type == "And":
        return all(evaluate_item(record, f) for f in filters)
    else:
        return any(evaluate_item(record, f) for f in filters)


def evaluate_rule(record, conditions_str):
    """
    Evaluate a rule's conditions against a record.

    The conditions are stored as a JSON string containing an array.
    The top-level array uses implicit AND logic - all items must pass.

    Args:
        record: The record object to evaluate
        conditions_str: JSON string of conditions array

    Returns:
